B.ak2=new A.bR("\ud83e\udd81","Leo libaax wuxuu jeclaa inuu la ciyaaro xayawaanka kale.","Leo the lion loved playing with other animals.","\u0623\u062d\u0628 \u0644\u064a\u0648 \u0627\u0644\u0623\u0633\u062f \u0627\u0644\u0644\u0639\u0628 \u0645\u0639 \u0627\u0644\u062d\u064a\u0648\u0627\u0646\u0627\u062a \u0627\u0644\u0623\u062e\u0631\u0649.")
B.ajM=new A.bR("\ud83d\udc30","Maalin maalmaha ka mid ah, bakayle yar ayaa ka cabsaday libaaxa.","One day, a small rabbit was afraid of the lion.","\u0641\u064a \u064a\u0648\u0645\u060c \u062e\u0627\u0641 \u0623\u0631\u0646\u0628 \u0635\u063a\u064a\u0631 \u0645\u0646 \u0627\u0644\u0623\u0633\u062f.")
B.ak5=new A.bR("\ud83c\udf38",'Leo wuxuu u keenay ubax casaan ah. "Kuma dhibi doono," ayuu yiri si naxariis leh.','Leo brought a pink flower. "I will not hurt you," he said kindly.','\u0623\u062d\u0636\u0631 \u0644\u064a\u0648 \u0632\u0647\u0631\u0629 \u0648\u0631\u062f\u064a\u0629. \u0642\u0627\u0644 \u0628\u0644\u0637\u0641: "\u0644\u0646 \u0623\u0624\u0630\u064a\u0643."')
