B.ak7=new A.bR("\ud83c\udf19","Habeenkii, dayaxu wuxuu u ifay sida laambad samada ah.","At night, the moon shone like a lamp in the sky.","\u0641\u064a \u0627\u0644\u0644\u064a\u0644\u060c \u0623\u0636\u0627\u0621 \u0627\u0644\u0642\u0645\u0631 \u0643\u0645\u0635\u0628\u0627\u062d \u0641\u064a \u0627\u0644\u0633\u0645\u0627\u0621.")
B.akc=new A.bR("\u2b50","Xiddiguhu waxay u dhalaalayeen sida dhagxaan dhalaalaya.","Stars twinkled like shining stones.","\u062a\u0623\u0644\u0642\u062a \u0627\u0644\u0646\u062c\u0648\u0645 \u0643\u0623\u062d\u062c\u0627\u0631 \u0644\u0627\u0645\u0639\u0629.")
B.ajO=new A.bR("\ud83d\ude34","Ilmuhu wuxuu xidhay indhihiisa, wuxuuna maqlay hees jilicsan.","The child closed their eyes and heard a soft song.","\u0623\u063a\u0645\u0636 \u0627\u0644\u0637\u0641\u0644 \u0639\u064a\u0646\u064a\u0647 \u0648\u0633\u0645\u0639 \u0623\u063a\u0646\u064a\u0629 \u0647\u0627\u062f\u0626\u0629.")
B.ak9=new A.bR("\ud83d\udca4","Habeen wanaagsan, geesi yar. Berri wax cusub ayaad baran doontaa.","Good night, little hero. Tomorrow you will learn something new.","\u062a\u0635\u0628\u062d \u0639\u0644\u0649 \u062e\u064a\u0631 \u0623\u064a\u0647\u0627 \u0627\u0644\u0628\u0637\u0644 \u0627\u0644\u0635\u063a\u064a\u0631. \u063a\u062f\u0627\u064b \u0633\u062a\u062a\u0639\u0644\u0645 \u0634\u064a\u0626\u0627\u064b \u062c\u062f\u064a\u062f\u0627\u064b.")
